INSERT INTO mmd_blog_post (title, url_key, excerpt, content, author, status, published_at, related_skus, source_sku, hero_image_url, meta_title, meta_description, meta_keywords, likes, created_at, updated_at) SELECT 'IoTFlow Tutorial: Create an API Key and Set Up Alerts (with Video)', 'iotflow-tutorial-create-api-key-set-up-alerts', 'Step-by-step IoTFlow tutorial with video: create an account-level API key, send sensor readings with it over HTTP, set up an alert rule that fires when a reading crosses a threshold, and install the IoTFlow mobile app.', '<p><strong>Short version:</strong> in <a href="https://iot.tertiaryinfotech.com" target="_blank" rel="noopener">IoTFlow</a>, open <strong>API Keys &rarr; Create API key</strong>, copy the <code>iot_&hellip;</code> key (it is shown only once), and send readings to <code>/api/telemetry</code> with <code>Authorization: Bearer &lt;key&gt;</code> plus the device&rsquo;s <code>deviceId</code> in the JSON body. For alerts, open <strong>Alerts &rarr; Create rule</strong>, pick a device, metric and threshold (for example temperature &gt; 30), and the alert appears within seconds of a reading crossing it. Both buttons need the <strong>Admin</strong> role &mdash; if you see &ldquo;Ask an administrator to create a key&rdquo;, that is why.</p> <p>This question came from one of our own trainers preparing an IoT class, so we recorded the whole flow end to end on a demo account. Watch the 90-second video, then follow the written steps below.</p> <figure class="mmd-blog-figure"><video controls playsinline preload="metadata" poster="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/iotflow/t7-video-poster.jpg" style="width:100%;height:auto;border-radius:10px;background:#000;display:block"><source src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/iotflow/iotflow-api-keys-alerts-tutorial.mp4" type="video/mp4" /></video><figcaption>Walkthrough: create an API key, send a reading, create an alert rule, trigger it and resolve it, then get the mobile app. <a href="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/iotflow/iotflow-api-keys-alerts-tutorial.mp4" target="_blank" rel="noopener">Download the video (MP4, 2 MB)</a>.</figcaption></figure> <p>Want to build the sensors that feed a platform like this? Our <a href="https://www.tertiarycourses.com.sg/wsq-iot-robotics-courses.html">WSQ IoT and Robotics courses</a> cover Arduino, ESP32, Raspberry Pi and MQTT hands-on, with up to 70% WSQ funding and SkillsFuture Credit eligible.</p> <h2>Before you start: why the buttons are missing</h2> <p>IoTFlow has two roles. Regular <strong>User</strong> accounts can add devices, build dashboards and send data, but only <strong>Admin</strong> accounts can create API keys and alert rules. On a User account the <strong>Create API key</strong> and <strong>Create rule</strong> buttons are hidden and the page says &ldquo;Ask an administrator&rdquo;.</p> <p>Ask your IoTFlow administrator to change your role to Admin under <strong>Admin &rarr; Users</strong>. It applies within about 30 seconds &mdash; just refresh, no sign-out needed. Admins also see an <strong>Admin | User</strong> toggle in the top bar; keep it on Admin, or the create buttons stay hidden. If you run your own self-hosted copy of IoTFlow, the first account you seed is already an Admin.</p> <h2>API key or device token: which one do you need?</h2> <p>IoTFlow accepts two kinds of credential on the same telemetry endpoint. For a single board, the device token is simpler &mdash; it is what the built-in tutorials use.</p> <table> <thead><tr><th>Credential</th><th>Looks like</th><th>Where you get it</th><th>Best for</th></tr></thead> <tbody> <tr><td>Device token</td><td><code>dev_&hellip;</code></td><td>Each device&rsquo;s page, under <em>Device token</em></td><td>One board talking for itself. No Admin role needed.</td></tr> <tr><td>API key</td><td><code>iot_&hellip;</code></td><td><strong>API Keys</strong> page (Admin only)</td><td>One gateway or script reporting for several devices. Include <code>deviceId</code> in every message.</td></tr> </tbody> </table> <h2>How to create an API key in IoTFlow</h2> <ol> <li>Sign in at <a href="https://iot.tertiaryinfotech.com" target="_blank" rel="noopener">iot.tertiaryinfotech.com</a>.</li> <li>In the left menu, click <strong>API Keys</strong>, then <strong>Create API key</strong> at the top right.</li> <li>Type a name you will recognise later, such as <em>Classroom sensors</em>, and click <strong>Create</strong>.</li> <li>Click <strong>Copy</strong> straight away and store the key somewhere safe, such as a password manager or your script&rsquo;s config file. It starts with <code>iot_</code> and is <strong>shown only once</strong>: IoTFlow keeps only its prefix.</li> <li>Click <strong>Done</strong>. The key now appears under <em>Your keys</em> with its prefix, creation date and when it was last used.</li> </ol> <figure class="mmd-blog-figure"><img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/iotflow/t7-create-api-key.jpg" alt="IoTFlow Create API key dialog with the key name Classroom sensors" width="1100" height="688" loading="lazy" /><figcaption>Name the key after where it will be used.</figcaption></figure> <figure class="mmd-blog-figure"><img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/iotflow/t7-copy-api-key.jpg" alt="IoTFlow dialog showing a newly created API key with a Copy button" width="1100" height="688" loading="lazy" /><figcaption>The full key is displayed once, right after creation. Copy it before you click Done.</figcaption></figure> <p>Lost a key, or pasted it somewhere public? Click the bin icon next to it to revoke it and create a new one. Anything still using the old key stops sending data immediately.</p> <h2>How to send data with the API key</h2> <ol> <li>Open <strong>Devices</strong>, click your device and copy its <strong>Device ID</strong> (for example <code>class-sensor-01</code>). This is the short public ID, not the long internal one.</li> <li>POST your readings to <code>/api/telemetry</code> with the key as a Bearer token and the Device ID in the body:</li> </ol> <pre><code>curl -X POST https://iot.tertiaryinfotech.com/api/telemetry \&#10;  -H "Authorization: Bearer iot_YOUR_API_KEY" \&#10;  -H "Content-Type: application/json" \&#10;  -d ''{"deviceId": "YOUR_DEVICE_ID", "temperature": 27.4, "humidity": 63}''</code></pre> <p>The same call from Python, which works on a Raspberry Pi or any laptop:</p> <pre><code>import requests&#10;&#10;r = requests.post(&#10;    "https://iot.tertiaryinfotech.com/api/telemetry",&#10;    headers={"Authorization": "Bearer iot_YOUR_API_KEY"},&#10;    json={"deviceId": "YOUR_DEVICE_ID", "temperature": 27.4, "humidity": 63},&#10;)&#10;print(r.status_code, r.json())</code></pre> <p>A successful call returns <strong>HTTP 201</strong> with a body such as <code>{"ok":true,"deviceId":"class-sensor-01","stored":2,"alerts":0}</code>. Every number in the body becomes its own metric &mdash; here <code>temperature</code> and <code>humidity</code> &mdash; and appears on the device page and the Telemetry page straight away.</p> <p>Teaching or learning IoT? Our <a href="https://www.tertiarycourses.com.sg/wsq-internet-of-things-iot-fundamental-for-beginners.html">WSQ Internet of Things (IoT) Fundamental for Beginners</a> course walks through sensors, MQTT and cloud dashboards in class. Browse all <a href="https://www.tertiarycourses.com.sg/wsq-iot-robotics-courses.html">WSQ IoT and Robotics courses</a> to find the right level.</p> <h2>How to set up an alert in IoTFlow</h2> <p>An alert rule watches one metric on one device. The device must have sent at least one reading first, because the <em>Metric</em> list is built from data it has already sent &mdash; until then it shows &ldquo;No telemetry yet&rdquo;.</p> <ol> <li>Choose the right project in the selector at the top of the left menu. The Alerts page only lists devices in the current project.</li> <li>Click <strong>Alerts</strong>, then <strong>Create rule</strong>.</li> <li>Enter a <strong>Rule name</strong> (for example <em>High temperature</em>) and pick the <strong>Device</strong>.</li> <li>Choose a <strong>Condition</strong>: greater than, less than, greater or equal, less or equal, equals, or <em>device offline</em>.</li> <li>Pick the <strong>Metric</strong> and type the <strong>Threshold</strong>, for example temperature greater than 30. For <em>device offline</em> you enter how many seconds of silence count as offline instead (the default is 600 seconds).</li> <li>Click <strong>Create rule</strong>. It appears under <em>Alert rules</em>, already enabled; untick it to pause it or use the bin icon to delete it.</li> </ol> <figure class="mmd-blog-figure"><img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/iotflow/t7-create-alert-rule.jpg" alt="IoTFlow Create alert rule form set to temperature greater than 30 on Classroom Sensor" width="1100" height="688" loading="lazy" /><figcaption>A rule that fires when the classroom temperature goes above 30&deg;C.</figcaption></figure> <h3>Test the alert, then resolve it</h3> <p>Send one reading above the threshold &mdash; for example <code>"temperature": 34.5</code> with the command above. Within a few seconds the alert appears under <strong>Active alerts</strong>, and in the mobile app. Click <strong>Resolve</strong> once it is handled. While an alert is active the same rule will not raise duplicates; after you resolve it, the next reading that crosses the threshold raises a new one.</p> <figure class="mmd-blog-figure"><img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/iotflow/t7-active-alert.jpg" alt="IoTFlow Active alerts list showing Classroom Sensor temperature 34.5 above threshold 30 with a Resolve button" width="1100" height="688" loading="lazy" /><figcaption>The triggered alert, ready to resolve.</figcaption></figure> <p>Alerts always show on the Alerts page and in the app. To push them somewhere else &mdash; Telegram, Slack, email or a Google Sheet &mdash; add an automation on the <strong>Automations</strong> page with the <em>Alert</em> trigger, which forwards each alert to an n8n workflow.</p> <h2>Get the IoTFlow mobile app</h2> <ul> <li><strong>iPhone and iPad:</strong> search for <strong>IoTFlow</strong> on the App Store, or open <a href="https://apps.apple.com/us/app/iotflow/id6781005693" target="_blank" rel="noopener">IoTFlow on the App Store</a>.</li> <li><strong>Android:</strong> the app is in Google Play closed testing, so it does not appear in a Play Store search yet. <a href="https://www.tertiarycourses.com.sg/contacts">Contact us</a> with the Gmail address on your phone and we will add you as a tester.</li> <li><strong>Sign in</strong> with the same email and password as the website. The app connects to iot.tertiaryinfotech.com by default. If you registered with &ldquo;Continue with Google&rdquo;, set a password first with <em>Forgot password</em> on the website, because the app signs in with email and password.</li> </ul> <p>The app mirrors the web dashboard: live widgets, switches and sliders that control your devices, your device list, alerts and automations.</p> <h2>Troubleshooting</h2> <table> <thead><tr><th>You see</th><th>Cause and fix</th></tr></thead> <tbody> <tr><td>No <em>Create API key</em> or <em>Create rule</em> button</td><td>Your account is not an Admin yet, or the top-bar toggle is on <em>User</em>. Switch it to Admin and refresh.</td></tr> <tr><td>401 &ldquo;Invalid API key or missing deviceId in body&rdquo;</td><td>The key is wrong or revoked, or <code>deviceId</code> is missing from the JSON. Check the header reads exactly <code>Authorization: Bearer iot_&hellip;</code>.</td></tr> <tr><td>401 &ldquo;Unauthorized device&rdquo;</td><td>The <code>deviceId</code> is not one of your devices. An API key only works with devices owned by the account that created it.</td></tr> <tr><td>400 &ldquo;Invalid JSON body&rdquo;</td><td>The body is not valid JSON. On Windows Command Prompt, single quotes do not work in <code>-d</code>; use the Python example instead.</td></tr> <tr><td>Metric list says &ldquo;No telemetry yet&rdquo;</td><td>Send one reading from the device first, then open Create rule again.</td></tr> </tbody> </table> <h2>Frequently asked questions</h2> <div class="mmd-faq"> <details class="mmd-faq-item"><summary class="mmd-faq-q">Why does IoTFlow say &ldquo;Ask an administrator to create a key&rdquo;?</summary><div class="mmd-faq-a"><p>Creating API keys and alert rules is limited to Admin accounts. Ask your administrator to set your role to Admin under Admin &rarr; Users; it takes effect within about 30 seconds without signing out.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">What is the difference between an API key and a device token?</summary><div class="mmd-faq-a"><p>A device token (<code>dev_&hellip;</code>) belongs to one device and identifies it automatically. An API key (<code>iot_&hellip;</code>) belongs to your account and works for all your devices, so each message must name the device with <code>deviceId</code>.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">I lost my API key. Can I see it again?</summary><div class="mmd-faq-a"><p>No. IoTFlow stores only the key&rsquo;s prefix, so the full key is shown once. Revoke the old key with the bin icon and create a new one.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">Can I get an alert when a device stops sending data?</summary><div class="mmd-faq-a"><p>Yes. Choose the <em>device offline</em> condition and set how many seconds of silence count as offline. The alert is raised when the device has not reported for longer than that.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">Can IoTFlow send alerts to Telegram or email?</summary><div class="mmd-faq-a"><p>Yes. Create an automation with the Alert trigger and point it at an n8n workflow, which can forward the alert to Telegram, Slack, email, WhatsApp or a spreadsheet. Email alerts can also be switched on centrally by the platform administrator.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">Is there an IoT course in Singapore that covers this hands-on?</summary><div class="mmd-faq-a"><p>Yes. Our <a href="https://www.tertiarycourses.com.sg/wsq-iot-robotics-courses.html">WSQ IoT and Robotics courses</a> cover Arduino, ESP32, Raspberry Pi, MQTT and IoT dashboards hands-on, with up to 70% WSQ funding for eligible learners and SkillsFuture Credit claimable on top.</p></div></details> </div> <h2>Keep going</h2> <p>New to IoTFlow? Start with our earlier post, <a href="https://www.tertiarycourses.com.sg/blog/iotflow-self-hosted-iot-platform-python-sdk">Build Your Own IoT Backend: IoTFlow, a Self-Hosted Platform with a Python SDK</a>, then follow the full tutorial with copy-paste snippets at <a href="https://iot.tertiaryinfotech.com/tutorials/api-keys-and-alerts" target="_blank" rel="noopener">iot.tertiaryinfotech.com/tutorials</a>.</p> <p><strong>Ready to build real IoT projects in class?</strong> Explore the <a href="https://www.tertiarycourses.com.sg/wsq-iot-robotics-courses.html">WSQ IoT and Robotics course catalogue</a> &mdash; eligible learners get up to 70% WSQ funding, and Singaporeans can use SkillsFuture Credit to offset the rest.</p>', 'Tertiary Infotech Academy', 1, '2026-10-17', 'TGS-2020504020,TGS-2026064710,TGS-2026064711,TGS-2026066740,TGS-2020506075', NULL, 'https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/auto-20261017-054615-iotflow-tutorial-create-an-api-key-and-set-up-alerts-with.png', 'IoTFlow: Create an API Key and Set Up Alerts (Video Tutorial)', 'How to create an API key in IoTFlow, send telemetry with curl or Python, set up threshold and offline alerts, and get the mobile app. Step-by-step with video.', 'IoTFlow API key, IoT platform alerts, IoT telemetry API, create API key IoT, IoT alert rule threshold, IoT tutorial Singapore, MQTT HTTP telemetry, IoT course Singapore, WSQ IoT course', 74, '2026-10-17 14:00:00', '2026-10-17 14:00:00' FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM (SELECT post_id FROM mmd_blog_post WHERE url_key = 'iotflow-tutorial-create-api-key-set-up-alerts') existing);
